using System;
using UnityEditor;
using UnityEngine;

namespace Flightbeat.Editor
{
    public static class FlightbeatProjectSettings
    {
        [MenuItem("Flightbeat/Apply source project settings")]
        public static void Apply()
        {
            Require(Application.unityVersion == "2022.3.62f3", "fixed Editor version");
            PlayerSettings.companyName = "PixelWing";
            PlayerSettings.productName = "PixelWing";
            PlayerSettings.bundleVersion = "0.11.0";
            PlayerSettings.defaultScreenWidth = 540;
            PlayerSettings.defaultScreenHeight = 960;
            PlayerSettings.defaultWebScreenWidth = 960;
            PlayerSettings.defaultWebScreenHeight = 600;
            PlayerSettings.runInBackground = true;
            PlayerSettings.SplashScreen.show = true;
            PlayerSettings.SplashScreen.showUnityLogo = true;
            PlayerSettings.colorSpace = ColorSpace.Gamma;
            PlayerSettings.WebGL.compressionFormat = WebGLCompressionFormat.Gzip;
            PlayerSettings.WebGL.decompressionFallback = true;
            PlayerSettings.WebGL.template = "PROJECT:Flightbeat";
            AssetDatabase.SaveAssets();
            Verify();
        }

        // This only checks configuration import. It does not create a scene or a playable build.
        public static void Verify()
        {
            Require(PlayerSettings.companyName == "PixelWing", "companyName");
            Require(PlayerSettings.productName == "PixelWing", "productName");
            Require(PlayerSettings.bundleVersion == "0.11.0", "bundleVersion");
            Require(PlayerSettings.defaultScreenWidth == 540, "defaultScreenWidth");
            Require(PlayerSettings.defaultScreenHeight == 960, "defaultScreenHeight");
            Require(PlayerSettings.defaultWebScreenWidth == 960, "defaultScreenWidthWeb");
            Require(PlayerSettings.defaultWebScreenHeight == 600, "defaultScreenHeightWeb");
            Require(PlayerSettings.runInBackground == true, "runInBackground");
            Require(PlayerSettings.SplashScreen.show == true, "m_ShowUnitySplashScreen");
            Require(PlayerSettings.SplashScreen.showUnityLogo == true, "m_ShowUnitySplashLogo");
            Require(PlayerSettings.colorSpace == ColorSpace.Gamma, "m_ActiveColorSpace");
            Require(PlayerSettings.WebGL.compressionFormat == WebGLCompressionFormat.Gzip, "gzip format");
            Require(PlayerSettings.WebGL.decompressionFallback, "gzip fallback");
            Require(PlayerSettings.WebGL.template == "PROJECT:Flightbeat", "template");
            Require(Time.fixedDeltaTime == 0.02f, "Fixed Timestep");
            Require(Time.maximumDeltaTime == 0.3333333432674408f, "Maximum Allowed Timestep");
            Require(Time.timeScale == 1f, "m_TimeScale");
            Require(Time.maximumParticleDeltaTime == 0.029999999329447746f, "Maximum Particle Timestep");
            Require(QualitySettings.GetQualityLevel() == 3, "serialized current quality");
            string[] expectedNames = { "Very Low", "Low", "Medium", "High", "Very High", "Ultra" };
            string[] names = QualitySettings.names;
            Require(names.Length == expectedNames.Length, "quality level count");
            for (int i = 0; i < names.Length; i++)
                Require(names[i] == expectedNames[i], "quality name " + i);
            Debug.Log("Flightbeat source project settings applied and scalar import checks passed. Game and build acceptance remain pending.");
        }

        private static void Require(bool condition, string field)
        {
            if (!condition)
                throw new InvalidOperationException("Source configuration mismatch: " + field);
        }
